import { useState } from "react";

const ANOS_PINK = "#E8236A";
const ANOS_DARK = "#1a0a10";

const LOGO_PNG = "data:image/png;base64,";

const AnosLogo = ({ size = 60 }) => (
  <img
    src={LOGO_PNG}
    alt="ANOS FREE DIVING"
    style={{
      width: size,
      height: size,
      objectFit: "contain",
    }}
  />
);

const WaveBG = () => (
  <svg viewBox="0 0 400 80" preserveAspectRatio="none"
    style={{position:"absolute",bottom:0,left:0,width:"100%",height:60,opacity:0.15}}>
    <path d="M0,40 C60,10 120,70 180,40 C240,10 300,70 360,40 C390,25 400,30 400,30 L400,80 L0,80 Z" fill="#fff"/>
    <path d="M0,55 C80,30 160,70 240,48 C300,30 360,60 400,50 L400,80 L0,80 Z" fill="#fff" opacity="0.5"/>
  </svg>
);

const BubbleDots = () => (
  <svg viewBox="0 0 400 320" style={{position:"absolute",inset:0,width:"100%",height:"100%",pointerEvents:"none",opacity:0.12}}>
    {[{cx:25,cy:50,r:5},{cx:375,cy:70,r:4},{cx:40,cy:220,r:3},{cx:370,cy:240,r:6},{cx:200,cy:18,r:3},{cx:330,cy:160,r:3},{cx:70,cy:270,r:4}].map((b,i)=>(
      <circle key={i} cx={b.cx} cy={b.cy} r={b.r} fill="#fff"/>
    ))}
  </svg>
);

const couponTypes = [
  { label: "프리다이빙 체험 (3시간)", value: "FULL", price: "₩50,000", desc: "이론 교육 + 수중 실습 + 장비 대여 포함" },
];

function CouponCard({ data }) {
  const type = couponTypes[0];
  const [code] = useState(`ANOS-${Math.random().toString(36).slice(2,6).toUpperCase()}`);

  return (
    <div style={{
      width: "100%",
      maxWidth: 400,
      background: "linear-gradient(140deg, #f02575 0%, #c01055 55%, #8b0038 100%)",
      borderRadius: 22,
      overflow: "hidden",
      fontFamily: "'Georgia', serif",
      boxShadow: "0 16px 50px rgba(232,35,106,0.5), 0 4px 16px rgba(0,0,0,0.35)",
      position: "relative",
      userSelect: "none",
      boxSizing: "border-box",
    }}>
      <BubbleDots />

      {/* 헤더 */}
      <div style={{padding:"22px 24px 0",position:"relative",zIndex:2}}>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:0}}>
          <AnosLogo size={58} color="#fff"/>
          <div>
            <div style={{color:"#fff",fontSize:9,letterSpacing:4,fontFamily:"Arial,sans-serif",fontWeight:800,opacity:0.9,lineHeight:1.6}}>ANOS FREE DIVING</div>
            <div style={{color:"rgba(255,255,255,0.65)",fontSize:7.5,letterSpacing:2,fontFamily:"Arial,sans-serif"}}>EST. 2019 · SEOUL, REPUBLIC OF KOREA</div>
          </div>
        </div>
        <div style={{height:1,background:"rgba(255,255,255,0.22)",margin:"14px 0 12px"}}/>
        <div style={{color:"rgba(255,255,255,0.85)",fontSize:10,letterSpacing:5,fontFamily:"Arial,sans-serif",fontWeight:700}}>EXPERIENCE VOUCHER</div>
        <div style={{color:"#fff",fontSize:30,fontWeight:700,lineHeight:1.1,marginTop:4,textShadow:"0 2px 10px rgba(0,0,0,0.2)"}}>
          프리다이빙<br/>체험권
        </div>
      </div>

      {/* 바디 */}
      <div style={{padding:"14px 24px",position:"relative",zIndex:2}}>
        <div style={{background:"rgba(255,255,255,0.13)",borderRadius:14,padding:"13px 16px",border:"1px solid rgba(255,255,255,0.2)"}}>
          <div style={{color:"rgba(255,255,255,0.72)",fontSize:9,letterSpacing:3,fontFamily:"Arial,sans-serif",marginBottom:4}}>PROGRAM</div>
          <div style={{color:"#fff",fontSize:15,fontWeight:700,fontFamily:"Arial,sans-serif"}}>{type.label}</div>
          <div style={{color:"rgba(255,255,255,0.72)",fontSize:10,fontFamily:"Arial,sans-serif",marginTop:3}}>{type.desc}</div>
        </div>

        <div style={{display:"flex",gap:10,marginTop:10}}>
          <div style={{flex:1,background:"rgba(255,255,255,0.13)",borderRadius:12,padding:"11px 13px",border:"1px solid rgba(255,255,255,0.2)",minWidth:0}}>
            <div style={{color:"rgba(255,255,255,0.7)",fontSize:8,letterSpacing:3,fontFamily:"Arial,sans-serif"}}>NAME</div>
            <div style={{color:"#fff",fontSize:14,fontWeight:700,fontFamily:"Arial,sans-serif",marginTop:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{data.name || "—"}</div>
          </div>
          <div style={{flex:1,background:"rgba(255,255,255,0.13)",borderRadius:12,padding:"11px 13px",border:"1px solid rgba(255,255,255,0.2)",minWidth:0}}>
            <div style={{color:"rgba(255,255,255,0.7)",fontSize:8,letterSpacing:3,fontFamily:"Arial,sans-serif"}}>VALID UNTIL</div>
            <div style={{color:"#fff",fontSize:13,fontWeight:700,fontFamily:"Arial,sans-serif",marginTop:2}}>{data.expiry || "—"}</div>
          </div>
        </div>

        {data.note && (
          <div style={{marginTop:10,background:"rgba(255,255,255,0.1)",borderRadius:10,padding:"10px 13px",border:"1px solid rgba(255,255,255,0.15)"}}>
            <div style={{color:"rgba(255,255,255,0.7)",fontSize:8,letterSpacing:3,fontFamily:"Arial,sans-serif",marginBottom:3}}>NOTE</div>
            <div style={{color:"#fff",fontSize:11,fontFamily:"Arial,sans-serif",lineHeight:1.5}}>{data.note}</div>
          </div>
        )}
      </div>

      {/* 티어라인 */}
      <div style={{position:"relative",zIndex:2,margin:"4px 0"}}>
        <div style={{display:"flex",alignItems:"center",padding:"0 18px",position:"relative"}}>
          <div style={{width:20,height:20,borderRadius:"50%",background:ANOS_DARK,position:"absolute",left:-10}}/>
          <div style={{flex:1,borderTop:"2px dashed rgba(255,255,255,0.3)"}}/>
          <div style={{width:20,height:20,borderRadius:"50%",background:ANOS_DARK,position:"absolute",right:-10}}/>
        </div>
      </div>

      {/* 푸터 */}
      <div style={{padding:"12px 24px 20px",position:"relative",zIndex:2,display:"flex",justifyContent:"space-between",alignItems:"flex-end"}}>
        <div>
          <div style={{color:"rgba(255,255,255,0.65)",fontSize:8,letterSpacing:3,fontFamily:"Arial,sans-serif"}}>COUPON CODE</div>
          <div style={{color:"#fff",fontSize:13,fontWeight:700,fontFamily:"monospace",letterSpacing:2,marginTop:2}}>{code}</div>
        </div>
        <div style={{textAlign:"right"}}>
          <div style={{color:"rgba(255,255,255,0.65)",fontSize:8,letterSpacing:2,fontFamily:"Arial,sans-serif"}}>VALUE</div>
          <div style={{color:"#fff",fontSize:24,fontWeight:700,fontFamily:"Arial,sans-serif"}}>₩50,000</div>
        </div>
      </div>

      <WaveBG />
    </div>
  );
}

export default function App() {
  const [form, setForm] = useState({ name: "", expiry: "", note: "" });
  const [couponData, setCouponData] = useState(null);

  const handleGenerate = () => setCouponData({ ...form });

  const inputStyle = {
    width: "100%",
    background: "#1e0c14",
    border: "1px solid rgba(232,35,106,0.3)",
    borderRadius: 10,
    color: "#fff",
    padding: "11px 14px",
    fontSize: 14,
    fontFamily: "Arial, sans-serif",
    outline: "none",
    boxSizing: "border-box",
  };
  const labelStyle = {
    color: "rgba(255,255,255,0.6)",
    fontSize: 10,
    letterSpacing: 3,
    fontFamily: "Arial, sans-serif",
    display: "block",
    marginBottom: 6,
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: "radial-gradient(ellipse at top, #2d0a1a 0%, #0d0408 70%)",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      padding: "32px 16px",
      gap: 28,
      boxSizing: "border-box",
    }}>
      {/* 타이틀 */}
      <div style={{textAlign:"center"}}>
        <div style={{color:ANOS_PINK,fontSize:10,letterSpacing:6,fontFamily:"Arial,sans-serif",fontWeight:700,marginBottom:6}}>ANOS FREE DIVING</div>
        <div style={{color:"#fff",fontSize:24,fontFamily:"Georgia,serif",fontWeight:700}}>체험권 쿠폰 생성기</div>
        <div style={{color:"rgba(255,255,255,0.4)",fontSize:11,fontFamily:"Arial,sans-serif",marginTop:4}}>Experience Voucher Generator</div>
      </div>

      <div style={{display:"flex",flexWrap:"wrap",gap:24,justifyContent:"center",alignItems:"flex-start",width:"100%",maxWidth:860}}>
        {/* 폼 */}
        <div style={{
          background:"rgba(255,255,255,0.04)",
          border:"1px solid rgba(232,35,106,0.2)",
          borderRadius:20,
          padding:24,
          width:"100%",
          maxWidth:340,
          boxSizing:"border-box",
        }}>
          <div style={{display:"flex",flexDirection:"column",gap:16}}>
            <div>
              <label style={labelStyle}>수강생 이름 / NAME</label>
              <input style={inputStyle} placeholder="홍길동" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/>
            </div>
            <div>
              <label style={labelStyle}>유효기간 / VALID UNTIL</label>
              <input style={inputStyle} type="date" value={form.expiry} onChange={e=>setForm({...form,expiry:e.target.value})}/>
            </div>
            <div>
              <label style={labelStyle}>메모 / NOTE (선택)</label>
              <textarea style={{...inputStyle,height:68,resize:"none"}} placeholder="선물, 특이사항 등..." value={form.note} onChange={e=>setForm({...form,note:e.target.value})}/>
            </div>
            <button
              onClick={handleGenerate}
              style={{
                background:`linear-gradient(135deg, ${ANOS_PINK}, #c01055)`,
                color:"#fff",border:"none",borderRadius:12,padding:"14px",
                fontSize:14,fontWeight:700,fontFamily:"Arial,sans-serif",
                cursor:"pointer",letterSpacing:2,
                boxShadow:"0 8px 24px rgba(232,35,106,0.4)",
              }}
            >
              🤿 쿠폰 생성하기
            </button>
          </div>
        </div>

        {/* 미리보기 */}
        <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:14,width:"100%",maxWidth:400,boxSizing:"border-box"}}>
          {couponData ? (
            <>
              <div style={{color:"rgba(255,255,255,0.5)",fontSize:10,letterSpacing:4,fontFamily:"Arial,sans-serif"}}>PREVIEW</div>
              <CouponCard data={couponData}/>
              <div style={{color:"rgba(255,255,255,0.3)",fontSize:10,fontFamily:"Arial,sans-serif",textAlign:"center"}}>스크린샷으로 저장하거나 인쇄하세요</div>
            </>
          ) : (
            <div style={{
              width:"100%",height:220,
              border:"1px dashed rgba(232,35,106,0.2)",
              borderRadius:22,
              display:"flex",alignItems:"center",justifyContent:"center",
              flexDirection:"column",gap:12,
              boxSizing:"border-box",
            }}>
              <AnosLogo size={52} color="rgba(232,35,106,0.35)"/>
              <span style={{color:"rgba(255,255,255,0.2)",fontSize:13,fontFamily:"Arial,sans-serif"}}>쿠폰 미리보기</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
